  // CoverageQuestionPage / CoverageQuestion — control coverage on systems (a question page)
  'coverage.title': { title: 'Control coverage on systems', body: 'The question page behind the board’s control coverage ring. Every control objective recorded on a system that is not ruled not applicable is in place, in place but degraded, or not in place. Answer it by objective, by system, by department, or list the degraded controls. An Information Asset Owner or Manager sees their own department.' },
  'coverage.worst': { title: 'Worst covered', body: 'The lowest share in place first; where two are level, the one with more not in place is worse.' },
