  'coverage.col.why': { title: 'Why', body: 'Why it is low, where CIRKS can tell. An objective in place nowhere usually has no security solution: the security function’s to fix. A system with little in place usually has no pattern stated or an incomplete record: its department’s to fix.' },
  'coverage.col.risks': { title: 'Risks it counters', body: 'The active risks on this system whose threat this objective counters.' },
  'coverage.col.highest': { title: 'Highest risk', body: 'The highest score among the risks it counters on this system: fixing the degraded control lowers this one first.' },
