  'decisions.col.waiting': { title: 'Waiting', body: 'How long the step has waited: since the risk was created (to validate), returned (to correct) or validated (to decide or agree).' },
  'decisions.col.department': { title: 'Department', body: 'The department owning the systems. Choose it to see its risks waiting.' },
  'decisions.col.count': { title: 'Waiting', body: 'Risks at or above the action threshold in this department still waiting for a decision.' },
